import numpy as np

class NeuralNetwork:
    def __init__(self, in_sz, hid_sz, out_sz):
        self.W1 = np.random.randn(in_sz, hid_sz) * 0.01
        self.b1 = np.zeros((1, hid_sz))
        self.W2 = np.random.randn(hid_sz, out_sz) * 0.01
        self.b2 = np.zeros((1, out_sz))
    def relu(self, z): return np.maximum(0, z)
    def softmax(self, z):
        e = np.exp(z - z.max(axis=1, keepdims=True))
        return e / e.sum(axis=1, keepdims=True)
    def forward(self, X):
        self.h = self.relu(X @ self.W1 + self.b1)
        return self.softmax(self.h @ self.W2 + self.b2)
    def loss(self, p, y): return -np.log(p[range(len(y)), y]).mean()

X = np.array([[0,0],[0,1],[1,0],[1,1]])
y = np.array([0,1,1,0])
model = NeuralNetwork(2, 8, 2)
for i in range(1000):
    out = model.forward(X)
    if i % 200 == 0: print(f'Step {i}: loss={model.loss(out,y):.4f}')
print('Preds:', np.argmax(model.forward(X), axis=1))

import torch.nn as nn

class SimpleCNN(nn.Module):
    def __init__(self):
        super().__init__()
        self.features = nn.Sequential(
            nn.Conv2d(1, 32, 3, padding=1), nn.ReLU(), nn.MaxPool2d(2),
            nn.Conv2d(32, 64, 3, padding=1), nn.ReLU(), nn.MaxPool2d(2))
        self.fc = nn.Sequential(nn.Linear(64*7*7, 128), nn.ReLU(), nn.Linear(128, 10))
    def forward(self, x):
        return self.fc(self.features(x).view(x.size(0), -1))

m = SimpleCNN()
print(f'Params: {sum(p.numel() for p in m.parameters()):,}')

import torch, torch.nn as nn

class Net(nn.Module):
    def __init__(self, dp=False):
        super().__init__()
        layers = [nn.Linear(20,128), nn.ReLU()]
        if dp: layers.append(nn.Dropout(0.5))
        layers += [nn.Linear(128,2)]
        self.net = nn.Sequential(*layers)
    def forward(self, x): return self.net(x)

X = torch.randn(300, 20)
y = (X[:,0]+X[:,1]>0).long()

for name, dp in [('No DP', False), ('With DP', True)]:
    m = Net(dp)
    opt = torch.optim.Adam(m.parameters())
    for _ in range(500):
        loss = nn.CrossEntropyLoss()(m(X), y)
        opt.zero_grad(); loss.backward(); opt.step()
    print(f'{name}: train_acc={((m(X).argmax(1)==y).float().mean()):.3f}')

import torch.nn as nn

class PatchEmbed(nn.Module):
    def __init__(self, img=224, patch=16, ch=3, dim=768):
        super().__init__()
        self.proj = nn.Conv2d(ch, dim, patch, stride=patch)
    def forward(self, x): return self.proj(x).flatten(2).transpose(1,2)

pe = PatchEmbed()
img = torch.randn(2, 3, 224, 224)
patches = pe(img)
print(f'Image: {img.shape} -> Patches: {patches.shape} ({(224//16)**2} patches of 768-dim)')

def bpe(text, n_merges=5):
    tokens = list(text.encode())
    for i in range(n_merges):
        pairs = {}
        for j in range(len(tokens)-1):
            p = (tokens[j], tokens[j+1])
            pairs[p] = pairs.get(p, 0) + 1
        if not pairs: break
        best = max(pairs, key=pairs.get)
        new = [best[0]*256+best[1]]
        merged = []
        j = 0
        while j < len(tokens):
            if j < len(tokens)-1 and (tokens[j],tokens[j+1]) == best:
                merged.append(256+i); j += 2
            else:
                merged.append(tokens[j]); j += 1
        tokens = merged
        print(f'Merge {i+1}: {best} -> {256+i}')
    return tokens

result = bpe('the cat sat on the mat ' * 3)
print(f'Final tokens: {len(result)}')

import numpy as np

def cosine(a, b): return np.dot(a,b)/(np.linalg.norm(a)*np.linalg.norm(b))

np.random.seed(42)
emb = {'Python tutorial': np.random.randn(8), 'Java guide': np.random.randn(8),
       'ML intro': np.random.randn(8), 'Python data science': np.random.randn(8)}
query = np.random.randn(8)

results = sorted([(t, cosine(e, query)) for t,e in emb.items()], key=lambda x: x[1], reverse=True)
for t, s in results: print(f'{s:.4f} - {t}')

import numpy as np

def perplexity(log_probs):
    return np.exp(-np.mean(log_probs))

log_probs = [-0.1, -0.5, -0.3, -0.2, -0.8]
print(f'Perplexity: {perplexity(log_probs):.2f}')
print('Lower is better; 1.0 = perfect, vocab_size = random')
